/** The dock's injected stylesheet text. */
export declare const cssText = "\n.dsh_atFile_rail {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  min-width: 0;\n}\n.dsh_atFile_row {\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n  min-width: 0;\n  max-width: 100%;\n  height: 28px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 14px;\n  background: var(--dsw-alias-bg-layer-1);\n}\n.dsh_atFile_path {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  max-width: 360px;\n  height: 100%;\n  padding: 0 6px 0 10px;\n  border: 0;\n  background: none;\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  line-height: 18px;\n  cursor: pointer;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.dsh_atFile_path:hover {\n  color: var(--dsw-alias-brand-primary);\n}\n.dsh_atFile_icon {\n  flex: none;\n  width: 14px;\n  height: 14px;\n}\n.dsh_atFile_remove {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  width: 20px;\n  height: 20px;\n  margin-right: 4px;\n  border: 0;\n  border-radius: 10px;\n  background: none;\n  color: var(--dsw-alias-label-dimmed);\n  cursor: pointer;\n}\n.dsh_atFile_remove svg {\n  width: 12px;\n  height: 12px;\n}\n.dsh_atFile_remove:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_atFile_section {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  min-width: 0;\n}\n.dsh_atFile_title {\n  margin: 0;\n  color: var(--dsw-alias-label-primary);\n  font-size: 18px;\n  line-height: 26px;\n  font-weight: 600;\n}\n.dsh_atFile_card {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  min-width: 0;\n  padding: 14px 16px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 12px;\n  background: var(--dsw-alias-bg-layer-1);\n  cursor: pointer;\n}\n.dsh_atFile_checkbox {\n  flex: none;\n  width: 18px;\n  height: 18px;\n  margin: 2px 0 0;\n  accent-color: var(--dsw-alias-brand-primary);\n  cursor: pointer;\n}\n.dsh_atFile_cardText {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n.dsh_atFile_cardTitle {\n  color: var(--dsw-alias-label-primary);\n  font-size: 14px;\n  line-height: 22px;\n}\n.dsh_atFile_cardDesc {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_atFile_filter {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  min-width: 0;\n}\n.dsh_atFile_filterTitle {\n  color: var(--dsw-alias-label-primary);\n  font-size: 14px;\n  line-height: 22px;\n  font-weight: 600;\n}\n.dsh_atFile_filterDesc,\n.dsh_atFile_filterHint {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_atFile_filterInput {\n  box-sizing: border-box;\n  width: 100%;\n  min-width: 0;\n  min-height: 112px;\n  padding: 8px 10px;\n  resize: vertical;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  outline: none;\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_atFile_filterInput:focus {\n  border-color: var(--dsw-alias-brand-primary);\n}\n.dsh_atFile_filterActions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 8px;\n  min-width: 0;\n}\n.dsh_atFile_filterSave {\n  flex: none;\n  min-height: 32px;\n  padding: 0 14px;\n  border: 0;\n  border-radius: 16px;\n  background: var(--dsw-alias-button-primary-fill);\n  color: var(--dsw-alias-label-primary-inverted);\n  font: inherit;\n  font-size: 13px;\n  line-height: 20px;\n  cursor: pointer;\n}\n.dsh_atFile_filterSave:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\n";
